(4, 'Reiki', 'reiikierana@gmail.com', '$2b$10$P7uBMfNGZEsqyrpEzreOOubjeBfCOWF3kMX85Y.olr22zbunYMCy.', 'user', '9e1be655fe5056401cf8548b645291f3eb15ddf6');
INSERT INTO `weapons` (`id`, `name`, `rarity`, `base_atk`, `substat`, `passive`, `image`) VALUES
(1, 'A Thousand Blazing Suns', 5, 741, 'CRIT Rate 11.0%(2.4%)', 'Sunset Reignites the DawnGain the \"Scorching Brilliance\" effect when using an Elemental Skill or Burst: CRIT DMG increased by 20~40% and ATK increased by 28~56% for 6s. This effect can trigger once every 10s.While a \"Scorching Brilliance\" instance is active, its duration is increased by 2s after Normal or Charged attacks deal Elemental DMG. This effect can trigger once every second, and the max duration increase is 6s.Additionally, when the equipping character is in the Nightsoul\'s Blessing state, \"Scorching Brilliance\" effects are increased by 75%, and its duration will not count down when the equipping character is off—field.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/2c/Weapon_A_Thousand_Blazing_Suns.png'),
(2, 'A Thousand Floating Dreams', 5, 542, 'Elemental Mastery 265(58)', 'A Thousand Nights\' DawnsongParty members other than the equipping character will provide the equipping character with buffs based on whether their Elemental Type is the same as the latter or not. If their Elemental Types are the same, increase Elemental Mastery by 32~64. If not, increase the equipping character\'s DMG Bonus from their Elemental Type by 10~26%. Each of the aforementioned effects can have up to 3 stacks. Additionally, all nearby party members other than the equipping character will have their Elemental Mastery increased by 40~48. Multiple such effects from multiple such weapons can stack.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/4c/Weapon_A_Thousand_Floating_Dreams.png'),
(3, 'Absolution', 5, 674, 'CRIT DMG 44.1%(9.6%)', 'Deathly PactCRIT DMG increased by 20~40%. Increasing the value of a Bond of Life increases the DMG the equipping character deals by 16~32% for 6s. Max 3 stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/5f/Weapon_Absolution.png'),
(4, 'Amos\' Bow', 5, 608, 'ATK 49.6%(10.8%)', 'Strong-WilledIncreases Normal Attack and Charged Attack DMG by 12~24%. After a Normal or Charged Attack is fired, DMG dealt increases by a further 8~16% every 0.1 seconds the arrow is in the air for up to 5 times.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/de/Weapon_Amos%27_Bow.png'),
(5, 'Aqua Simulacra', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'The Cleansing FormHP is increased by 16~32%. When there are opponents nearby, the DMG dealt by the wielder of this weapon is increased by 20~40%. This will take effect whether the character is on-field or not.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/cd/Weapon_Aqua_Simulacra.png'),
(6, 'Aquila Favonia', 5, 674, 'Physical DMG Bonus 41.3%(9%)', 'Falcon\'s DefianceATK is increased by 20~40%. Triggers on taking DMG: the soul of the Falcon of the West awakens, holding the banner of the resistance aloft, regenerating HP equal to 100~160% of ATK and dealing 200~320% of ATK as DMG to surrounding opponents. This effect can only occur once every 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/6a/Weapon_Aquila_Favonia.png'),
(7, 'Astral Vulture\'s Crimson Plumage', 5, 608, 'CRIT DMG 66.2%(14.4%)', 'The Moonring SightedFor 12s after triggering a Swirl reaction, ATK increases by 24~48%. In addition, when 1/2 or more characters in the party are of a different Elemental Type from the equipping character, the DMG dealt by the equipping character\'s Charged Attacks is increased by 20/48~40/96% and Elemental Burst DMG dealt is increased by 10/24~20/48%.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/97/Weapon_Astral_Vulture%27s_Crimson_Plumage.png'),
(8, 'Athame Artis', 5, 608, 'CRIT Rate 33.1%(7.2%)', 'Day King\'s Splendor SolisCRIT DMG from Elemental Bursts is increased by 16~32%. When an Elemental Burst hits an opponent, gain the Blade of the Daylight Hours effect: ATK is increased by 20~40%. Nearby active party members other than the equipping character have their ATK increased by 16~32% for 3s.Additionally, when the party possesses Hexerei: Secret Rite effects, the effects of Blade of the Daylight Hours are increased by an additional 75%. This effect can be triggered even if the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/83/Weapon_Athame_Artis.png'),
(9, 'Azurelight', 5, 674, 'CRIT Rate 22.1%(4.8%)', 'White Mountain\'s BountyWithin 12s after an Elemental Skill is used, ATK is increased by 24~48%. During this time, when the equipping character has 0 Energy, ATK will be further increased by 24~48%, and CRIT DMG will be increased by 40~80%.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/bd/Weapon_Azurelight.png'),
(10, 'Beacon of the Reed Sea', 5, 608, 'CRIT Rate 33.1%(7.2%)', 'Desert WatchAfter the character\'s Elemental Skill hits an opponent, their ATK will be increased by 20~40% for 8s. After the character takes DMG, their ATK will be increased by 20~40% for 8s. The 2 aforementioned effects can be triggered even when the character is not on the field. Additionally, when not protected by a shield, the character\'s Max HP will be increased by 32~64%.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/6c/Weapon_Beacon_of_the_Reed_Sea.png'),
(11, 'Bloodsoaked Ruins', 5, 674, 'CRIT Rate 22.1%(4.8%)', 'Mournful TributeFor 3.5s after using an Elemental Burst, the equipping character\'s Lunar-Charged DMG dealt to opponents is increased by 36~84%. Additionally, after triggering a Lunar-Charged reaction, the equipping character will gain Requiem of Ruin: CRIT DMG is increased by 28~56% for 6s. They will also regain 12~16 Elemental Energy. Elemental Energy can be restored this way once every 14s.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/79/Weapon_Bloodsoaked_Ruins.png'),
(12, 'Calamity Queller', 5, 741, 'ATK 16.5%(3.6%)', 'Extinguishing PreceptGain 12~24% All Elemental DMG Bonus. Obtain Consummation for 20s after using an Elemental Skill, causing ATK to increase by 3.2~6.4% per second. This ATK increase has a maximum of 6 stacks. When the character equipped with this weapon is not on the field, Consummation\'s ATK increase is doubled.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/8b/Weapon_Calamity_Queller.png'),
(13, 'Cashflow Supervision', 5, 674, 'CRIT Rate 22.1%(4.8%)', 'Golden Blood-TideATK is increased by 16~32%. When current HP increases or decreases, Normal Attack DMG will be increased by 16~32% and Charged Attack DMG will be increased by 14~28% for 4s. Max 3 stacks. This effect can be triggered once every 0.3s. When the wielder has 3 stacks, ATK SPD will be increased by 8~16%.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/f2/Weapon_Cashflow_Supervision.png'),
(14, 'Crane\'s Echoing Call', 5, 741, 'ATK 16.5%(3.6%)', 'Cloudfall AxiomAfter the equipping character hits an opponent with a Plunging Attack, all nearby party members\' Plunging Attacks will deal 28~80% increased DMG for 20s. When nearby party members hit opponents with Plunging Attacks, they will restore 2.5~3.5 Energy to the equipping character. Energy can be restored this way every 0.7s. This energy regain effect can be triggered even if the equipping character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/61/Weapon_Crane%27s_Echoing_Call.png'),
(15, 'Crimson Moon\'s Semblance', 5, 674, 'CRIT Rate 22.1%(4.8%)', 'Ashen Sun\'s ShadowGrants a Bond of Life equal to 25% of Max HP when a Charged Attack hits an opponent. This effect can be triggered up to once every 14s. In addition, when the equipping character has a Bond of Life, they gain a 12~28% DMG Bonus; if the value of the Bond of Life is greater than or equal to 30% of Max HP, then gain an additional 24~56% DMG.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/82/Weapon_Crimson_Moon%27s_Semblance.png'),
(16, 'Elegy for the End', 5, 608, 'Energy Recharge 55.1%(12%)', 'The Parting RefrainA part of the \"Millennial Movement\" that wanders amidst the winds.Increases Elemental Mastery by 60~120.When the Elemental Skills or Elemental Bursts of the character wielding this weapon hit opponents, that character gains a Sigil of Remembrance. This effect can be triggered once every 0.2s and can be triggered even if said character is not on the field.When you possess 4 Sigils of Remembrance, all of them will be consumed and all nearby party members will obtain the \"Millennial Movement: Farewell Song\" effect for 12s.\"Millennial Movement: Farewell Song\" increases Elemental Mastery by 100~200 and increases ATK by 20~40%. Once this effect is triggered, you will not gain Sigils of Remembrance for 20s.Of the many effects of the \"Millennial Movement,\" buffs of the same type will not stack.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/a5/Weapon_Elegy_for_the_End.png'),
(17, 'Engulfing Lightning', 5, 608, 'Energy Recharge 55.1%(12%)', 'Timeless Dream: Eternal StoveATK increased by 28~56% of Energy Recharge over the base 100%. You can gain a maximum bonus of 80~120% ATK. Gain 30~50% Energy Recharge for 12s after using an Elemental Burst.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/21/Weapon_Engulfing_Lightning.png'),
(18, 'Everlasting Moonglow', 5, 608, 'HP 49.6%(10.8%)', 'Byakuya KougetsuHealing Bonus increased by 10~20%, Normal Attack DMG is increased by 1~3.0% of the Max HP of the character equipping this weapon. For 12s after using an Elemental Burst, Normal Attacks that hit opponents will restore 0.6 Energy. Energy can be restored this way once every 0.1s.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/e1/Weapon_Everlasting_Moonglow.png'),
(19, 'Fang of the Mountain King', 5, 741, 'CRIT Rate 11.0%(2.4%)', 'Turquoise HuntGain 1 stack of Canopy\'s Favor after hitting an opponent with an Elemental Skill. This can be triggered once every 0.5s. After a nearby party member triggers a Burning or Burgeon reaction, the equipping character will gain 3 stacks. This effect can be triggered once every 2s and can be triggered even when the triggering party member is off-field. Canopy\'s Favor: Elemental Skill and Burst DMG is increased by 10~20% for 6s. Max 6 stacks. Each stack is counted independently.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/35/Weapon_Fang_of_the_Mountain_King.png'),
(20, 'Fractured Halo', 5, 608, 'CRIT DMG 66.2%(14.4%)', 'Purifying CrownAfter an Elemental Skill or Elemental Burst is used, ATK is increased by 24~48% for 20s. If the equipping character creates a Shield while this effect is active, they will gain the Electrifying Edict effect for 20s: All nearby party members deal 40~80% more Lunar-Charged DMG.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/10/Weapon_Fractured_Halo.png'),
(21, 'Freedom-Sworn', 5, 608, 'Elemental Mastery 198(43)', 'Revolutionary ChoraleA part of the \"Millennial Movement\" that wanders amidst the winds.Increases DMG by 10~20%.When the character wielding this weapon triggers Elemental Reactions, they gain a Sigil of Rebellion. This effect can be triggered once every 0.5s and can be triggered even if said character is not on the field.When you possess 2 Sigils of Rebellion, all of them will be consumed and all nearby party members will obtain \"Millennial Movement: Song of Resistance\" for 12s.\"Millennial Movement: Song of Resistance\" increases Normal, Charged, and Plunging Attack DMG by 16~32% and increases ATK by 20~40%. Once this effect is triggered, you will not gain Sigils of Rebellion for 20s.Of the many effects of the \"Millennial Movement,\" buffs of the same type will not stack.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/39/Weapon_Freedom-Sworn.png'),
(22, 'Gest of the Mighty Wolf', 5, 608, 'CRIT Rate 33.1%(7.2%)', 'Indomitable ChivalryIncrease ATK SPD by 10%. Every time the equipping character\'s Normal Attack(s) hit opponent(s), when they cast their Elemental Skill, or when they begin their Charged Attack(s), gain 1/2/2 stacks of Four Winds\' Hymn respectively: DMG dealt is increased by 7.5~15.5%, for 4s. Max 4 stacks. This effect can be triggered once every 0.01s.Additionally, when the team has the \"Hexerei: Secret Rite\" effect, each stack of Four Winds\' Hymn will increase the CRIT DMG of the equipping character by 7.5~15.5%.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/3b/Weapon_Gest_of_the_Mighty_Wolf.png'),
(23, 'Haran Geppaku Futsu', 5, 608, 'CRIT Rate 33.1%(7.2%)', 'Honed FlowObtain 12~24% All Elemental DMG Bonus. When other nearby party members use Elemental Skills, the character equipping this weapon will gain 1 Wavespike stack. Max 2 stacks. This effect can be triggered once every 0.3s. When the character equipping this weapon uses an Elemental Skill, all stacks of Wavespike will be consumed to gain Rippling Upheaval: each stack of Wavespike consumed will increase Normal Attack DMG by 20~40% for 8s.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/85/Weapon_Haran_Geppaku_Futsu.png'),
(24, 'Hunter\'s Path', 5, 542, 'CRIT Rate 44.1%(9.6%)', 'At the End of the Beast-PathsGain 12~24% All Elemental DMG Bonus. Obtain the Tireless Hunt effect after hitting an opponent with a Charged Attack. This effect increases Charged Attack DMG by 160~320% of Elemental Mastery. This effect will be removed after 12 Charged Attacks or 10s. Only 1 instance of Tireless Hunt can be gained every 12s.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/dd/Weapon_Hunter%27s_Path.png'),
(25, 'Jadefall\'s Splendor', 5, 608, 'HP 49.6%(10.8%)', 'Primordial Jade RegaliaFor 3s after using an Elemental Burst or creating a shield, the equipping character can gain the Primordial Jade Regalia effect: Restore 4.5~6.5 Energy every 2.5s, and gain 0.3~1.1% Elemental DMG Bonus for their corresponding Elemental Type for every 1,000 Max HP they possess, up to 12~44%. Primordial Jade Regalia will still take effect even if the equipping character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/7a/Weapon_Jadefall%27s_Splendor.png'),
(26, 'Kagura\'s Verity', 5, 608, 'CRIT DMG 66.2%(14.4%)', 'Kagura Dance of the Sacred SakuraGains the Kagura Dance effect when using an Elemental Skill, causing the Elemental Skill DMG of the character wielding this weapon to increase by 12~24% for 16s. Max 3 stacks. This character will gain 12~24% All Elemental DMG Bonus when they possess 3 stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/b7/Weapon_Kagura%27s_Verity.png'),
(27, 'Key of Khaj-Nisut', 5, 542, 'HP 66.2%(14.4%)', 'Sunken Song of the SandsHP increased by 20~40%. When an Elemental Skill hits opponents, you gain the Grand Hymn effect for 20s. This effect increases the equipping character\'s Elemental Mastery by 0.12~0.24% of their Max HP. This effect can trigger once every 0.3s. Max 3 stacks. When this effect gains 3 stacks, or when the third stack\'s duration is refreshed, the Elemental Mastery of all nearby party members will be increased by 0.2~0.4% of the equipping character\'s max HP for 20s.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/52/Weapon_Key_of_Khaj-Nisut.png'),
(28, 'Light of Foliar Incision', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'Whitemoon BristleCRIT Rate is increased by 4~8%. After Normal Attacks deal Elemental DMG, the Foliar Incision effect will be obtained, increasing DMG dealt by Normal Attacks and Elemental Skills by 120~240% of Elemental Mastery. This effect will disappear after 28 DMG instances or 12s. You can obtain Foliar Incision once every 12s.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/de/Weapon_Light_of_Foliar_Incision.png'),
(29, 'Lightbearing Moonshard', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'Legacy of Lang-GanIncreases DEF by 20~40%. DMG inflicted by Lunar-Crystallize reactions increases by 64~128% for 5s after the equipping character uses an Elemental Skill.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/f6/Weapon_Lightbearing_Moonshard.png'),
(30, 'Lost Prayer to the Sacred Winds', 5, 608, 'CRIT Rate 33.1%(7.2%)', 'Boundless BlessingIncreases Movement SPD by 10%. When in battle, gain an 8~16% Elemental DMG Bonus every 4s. Max 4 stacks. Lasts until the character falls or leaves combat.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/98/Weapon_Lost_Prayer_to_the_Sacred_Winds.png'),
(31, 'Lumidouce Elegy', 5, 608, 'CRIT Rate 33.1%(7.2%)', 'Bright Dawn OvertureATK increased by 15~31%. After the equipping character triggers Burning on an opponent or deals Dendro DMG to Burning opponents, the DMG dealt is increased by 18~38%. This effect lasts for 8s, max 2 stacks. When 2 stacks are reached or when the duration is refreshed at 2 stacks, restore 12~16 Energy. Energy can be restored this way once every 12s. The 2 aforementioned effects can be triggered even when the character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/8e/Weapon_Lumidouce_Elegy.png'),
(32, 'Memory of Dust', 5, 608, 'ATK 49.6%(10.8%)', 'Golden MajestyIncreases Shield Strength by 20~40%. Scoring hits on opponents increases ATK by 4~8% for 8s. Max 5 stacks. Can only occur once every 0.3s. While protected by a shield, this ATK increase effect is increased by 100%.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/ca/Weapon_Memory_of_Dust.png'),
(33, 'Mistsplitter Reforged', 5, 674, 'CRIT DMG 44.1%(9.6%)', 'Mistsplitter\'s EdgeGain a 12~24% Elemental DMG Bonus for all elements and receive the might of the Mistsplitter\'s Emblem. At stack levels 1/2/3, Mistsplitter\'s Emblem provides a 8/16/28~16/32/56% Elemental DMG Bonus for the character\'s Elemental Type. The character will obtain 1 stack of Mistsplitter\'s Emblem in each of the following scenarios: Normal Attack deals Elemental DMG (stack lasts 5s), casting Elemental Burst (stack lasts 10s); Energy is less than 100% (stack disappears when Energy is full). Each stack\'s duration is calculated independently.', 'https://static.wikia.nocookie.net/gensin-impact/images/0/09/Weapon_Mistsplitter_Reforged.png'),
(34, 'Nightweaver\'s Looking Glass', 5, 565, 'Elemental Mastery 265(58)', 'Millennial HymnWhen the equipping character\'s Elemental Skill deals Hydro or Dendro DMG, they will gain Prayer of the Far North: Elemental Mastery is increased by 60~120 for 4.5s. When nearby party members trigger Lunar-Bloom reactions, the equipping character gains New Moon Verse: Elemental Mastery is increased by 60~120 for 10s. When both Prayer of the Far North and New Moon Verse are in effect, all nearby party members\' Bloom DMG is increased by 120~240%, their Hyperbloom and Burgeon DMG is increased by 80~160%, and their Lunar-Bloom DMG is increased by 40~80%. This effect cannot stack. The aforementioned effects can be triggered even if the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/a7/Weapon_Nightweaver%27s_Looking_Glass.png'),
(35, 'Nocturne\'s Curtain Call', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'Ballad of the CrossroadsMax HP increases by 10~18%. When triggering Lunar reactions or inflicting Lunar Reaction DMG on opponents, the equipping character will recover 14~18 Energy, and receive the Bountiful Sea\'s Sacred Wine effect for 12s: Max HP increases by an additional 14~22%, CRIT DMG from Lunar Reaction DMG increases by 60~140%. The Energy recovery effect can be triggered at most once every 18s, and can be triggered even when the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/24/Weapon_Nocturne%27s_Curtain_Call.png'),
(36, 'Peak Patrol Song', 5, 542, 'DEF 82.7%(18%)', 'Halcyon Years UnendingGain \"Ode to Flowers\" after Normal or Plunging Attacks hit an opponent: DEF increases by 8~16% and gain a 10~20% All Elemental DMG Bonus for 6s. Max 2 stacks. Can trigger once per 0.1s. When this effect reaches 2 stacks or the 2nd stack\'s duration is refreshed, increase all nearby party members\' All Elemental DMG Bonus by 8~16% for every 1,000 DEF the equipping character has, up to a maximum of 25.6~51.2%, for 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/b4/Weapon_Peak_Patrol_Song.png'),
(37, 'Polar Star', 5, 608, 'CRIT Rate 33.1%(7.2%)', 'Daylight\'s AuguryElemental Skill and Elemental Burst DMG increased by 12~24%. After a Normal Attack, Charged Attack, Elemental Skill or Elemental Burst hits an opponent, 1 stack of Ashen Nightstar will be gained for 12s. When 1/2/3/4 stacks of Ashen Nightstar are present, ATK is increased by 10/20/30/48~20/40/60/96%. The stack of Ashen Nightstar created by the Normal Attack, Charged Attack, Elemental Skill or Elemental Burst will be counted independently of the others.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/44/Weapon_Polar_Star.png'),
(38, 'Primordial Jade Cutter', 5, 542, 'CRIT Rate 44.1%(9.6%)', 'Protector\'s VirtueHP increased by 20~40%. Additionally, provides an ATK Bonus based on 1.2~2.4% of the wielder\'s Max HP.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/2a/Weapon_Primordial_Jade_Cutter.png'),
(39, 'Primordial Jade Winged-Spear', 5, 674, 'CRIT Rate 22.1%(4.8%)', 'Eagle Spear of JusticeOn hit, increases ATK by 3.2~6.0% for 6s. Max 7 stacks. This effect can only occur once every 0.3s. While in possession of the maximum possible stacks, DMG dealt is increased by 12~24%.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/80/Weapon_Primordial_Jade_Winged-Spear.png'),
(40, 'Redhorn Stonethresher', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'Gokadaiou OtogibanashiDEF is increased by 28~56%. Normal and Charged Attack DMG is increased by 40~80% of DEF.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/d4/Weapon_Redhorn_Stonethresher.png'),
(41, 'Reliquary of Truth', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'Essence of FalsityCRIT Rate is increased by 8~16%. When the equipping character unleashes an Elemental Skill, they gain the Secret of Lies effect: Elemental Mastery is increased by 80~160 for 12s. When the equipping character deals Lunar-Bloom DMG to an opponent, they gain the Moon of Truth effect: CRIT DMG is increased by 24~48% for 4s. When both the Secret of Lies and Moon of Truth effects are active at the same time, the results of both effects will be increased by 50%.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/86/Weapon_Reliquary_of_Truth.png'),
(42, 'Silvershower Heartstrings', 5, 542, 'HP 66.2%(14.4%)', 'Dryas\'s NocturneThe equipping character can gain the Remedy effect. When they possess 1/2/3 Remedy stacks, Max HP will increase by 12/24/40~24/48/80. 1 stack may be gained when the following conditions are met: 1 stack for 25s when using an Elemental Skill; 1 stack for 25s when the value of a Bond of Life value increases; 1 stack for 20s for performing healing. Stacks can still be triggered when the equipping character is not on the field. Each stack\'s duration is counted independently. In addition, when 3 stacks are active, Elemental Burst CRIT Rate will be increased by 28~56. This effect will be canceled 4s after falling under 3 stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/41/Weapon_Silvershower_Heartstrings.png'),
(43, 'Skyward Atlas', 5, 674, 'ATK 33.1%(7.2%)', 'Wandering CloudsIncreases Elemental DMG Bonus by 12~24%. Normal Attack hits have a 50% chance to earn the favor of the clouds, which actively seek out nearby opponents to attack for 15s, dealing 160~320% ATK DMG. Can only occur once every 30s.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/33/Weapon_Skyward_Atlas.png'),
(44, 'Skyward Blade', 5, 608, 'Energy Recharge 55.1%(12%)', 'Sky-Piercing FangCRIT Rate increased by 4~8%. Gains Skypiercing Might upon using an Elemental Burst: Increases Movement SPD by 10%, increases ATK SPD by 10%, and Normal and Charged hits deal additional DMG equal to 20~40% of ATK. Skypiercing Might lasts for 12s.', 'https://static.wikia.nocookie.net/gensin-impact/images/0/03/Weapon_Skyward_Blade.png'),
(45, 'Skyward Harp', 5, 674, 'CRIT Rate 22.1%(4.8%)', 'Echoing BalladIncreases CRIT DMG by 20~40%. Hits have a 60~100% chance to inflict a small AoE attack, dealing 125% Physical ATK DMG. Can only occur once every 4~2s.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/19/Weapon_Skyward_Harp.png'),
(46, 'Skyward Pride', 5, 674, 'Energy Recharge 36.8%(8%)', 'Sky-ripping Dragon SpineIncreases all DMG by 8~16%. After using an Elemental Burst, a vacuum blade that does 80~160% of ATK as DMG to opponents along its path will be created when Normal or Charged Attacks hit. Lasts for 20s or 8 vacuum blades.', 'https://static.wikia.nocookie.net/gensin-impact/images/0/0b/Weapon_Skyward_Pride.png'),
(47, 'Skyward Spine', 5, 674, 'Energy Recharge 36.8%(8%)', 'Black WingIncreases CRIT Rate by 8~16% and increases Normal ATK SPD by 12%. Additionally, Normal and Charged Attacks hits on opponents have a 50% chance to trigger a vacuum blade that deals 40~100% of ATK as DMG in a small AoE. This effect can occur no more than once every 2s.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/69/Weapon_Skyward_Spine.png'),
(48, 'Song of Broken Pines', 5, 741, 'Physical DMG Bonus 20.7%(4.5%)', 'Rebel\'s Banner-HymnA part of the \"Millennial Movement\" that wanders amidst the winds.Increases ATK by 16~32%, and when Normal or Charged Attacks hit opponents, the character gains a Sigil of Whispers. This effect can be triggered once every 0.3s.When you possess four Sigils of Whispers, all of them will be consumed and all nearby party members will obtain the \"Millennial Movement: Banner-Hymn\" effect for 12s.\"Millennial Movement: Banner-Hymn\" increases Normal ATK SPD by 12~24% and increases ATK by 20~40%. Once this effect is triggered, you will not gain Sigils of Whispers for 20s.Of the many effects of the \"Millennial Movement\", buffs of the same type will not stack.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/dd/Weapon_Song_of_Broken_Pines.png'),
(49, 'Splendor of Tranquil Waters', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'Dawn and Dusk by the LakeWhen the equipping character\'s current HP increases or decreases, Elemental Skill DMG dealt will be increased by 8~16% for 6s. Max 3 stacks. This effect can be triggered once every 0.2s. When other party members\' current HP increases or decreases, the equipping character\'s Max HP will be increased by 14~28% for 6s. Max 2 stacks. This effect can be triggered once every 0.2s. The aforementioned effects can be triggered even if the wielder is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/4f/Weapon_Splendor_of_Tranquil_Waters.png'),
(50, 'Staff of Homa', 5, 608, 'CRIT DMG 66.2%(14.4%)', 'Reckless CinnabarHP increased by 20~40%. Additionally, provides an ATK Bonus based on 0.8~1.6% of the wielder\'s Max HP. When the wielder\'s HP is less than 50%, this ATK bonus is increased by an additional 1~1.8% of Max HP.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/17/Weapon_Staff_of_Homa.png'),
(51, 'Staff of the Scarlet Sands', 5, 542, 'CRIT Rate 44.1%(9.6%)', 'Heat Haze at Horizon\'s EndThe equipping character gains 52~104% of their Elemental Mastery as bonus ATK. When an Elemental Skill hits opponents, the Dream of the Scarlet Sands effect will be gained for 10s: The equipping character will gain 28~56% of their Elemental Mastery as bonus ATK. Max 3 stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/44/Weapon_Staff_of_the_Scarlet_Sands.png'),
(52, 'Starcaller\'s Watch', 5, 542, 'Elemental Mastery 265(58)', 'Offering Unto Wind and SunIncreases Elemental Mastery by 100~200. Gain the \"Mirror of Night\" effect within 15s after the equipping character creates a shield: The current active party member deals 28~56% increased DMG to nearby opponents. You can gain the \"Mirror of Night\" effect once every 14s.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/a4/Weapon_Starcaller%27s_Watch.png'),
(53, 'Summit Shaper', 5, 608, 'ATK 49.6%(10.8%)', 'Golden MajestyIncreases Shield Strength by 20~40%. Scoring hits on opponents increases ATK by 4~8% for 8s. Max 5 stacks. Can only occur once every 0.3s. While protected by a shield, this ATK increase effect is increased by 100%.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/ca/Weapon_Summit_Shaper.png'),
(54, 'Sunny Morning Sleep-In', 5, 542, 'Elemental Mastery 265(58)', 'Bathhouses, Hawks, and NarukamiElemental Mastery increases by 120~240 for 6s after triggering Swirl. Elemental Mastery increases by 96~192 for 9s after the wielder\'s Elemental Skill hits an opponent. Elemental Mastery increases by 32~64 for 30s after the wielder\'s Elemental Burst hits an opponent.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/91/Weapon_Sunny_Morning_Sleep-In.png'),
(55, 'Surf\'s Up', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'Aqua RemembranceMax HP increased by 20~40%. Once every 15s, for the 14s after using an Elemental Skill: Gain 4 Scorching Summer stacks. Each stack increases Normal Attack DMG by 12~24%. For the duration of the effect, every 1.5s, lose 1 stack after a Normal Attack hits an opponent; once every 1.5s, gain 1 stack after triggering a Vaporize reaction on an opponent. Max 4 Scorching Summer stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/8a/Weapon_Surf%27s_Up.png'),
(56, 'Symphonist of Scents', 5, 608, 'CRIT DMG 66.2%(14.4%)', 'Seasoned SymphonyATK is increased by 12~24%. When the equipping character is off-field, ATK is increased by an additional 12~24%. After initiating healing, the equipping character and the character(s) they have healed will obtain the \"Sweet Echoes\" effect, increasing their ATK by 32~64% for 3s. This effect can be triggered even if the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/5d/Weapon_Symphonist_of_Scents.png'),
(57, 'The Daybreak Chronicles', 5, 674, 'CRIT DMG 44.1%(9.6%)', 'Dawning Song of DaybreakThe equipping character gains Stirring Dawn Breeze: 3s after leaving combat, Normal Attack, Elemental Skill, and Elemental Burst DMG is increased by 60~120%. While in combat, this DMG Bonus will decrease by 10~20% per second until it reaches 0%. When the equipping character\'s Normal Attacks, Elemental Skills, or Elemental Bursts hit an opponent, the DMG Bonus for the corresponding DMG type is increased by 10~20% until it reaches 60~120%. This effect can be triggered once every 0.1s for each of the attack types mentioned above. This effect can be triggered even if the equipping character is off-field.Additionally, when the party possesses Hexerei: Secret Rite effects, when the equipping character\'s Normal Attacks, Elemental Skills, or Elemental Bursts hit an opponent, the DMG Bonus for all these DMG types is increased by 20~40% instead.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/5c/Weapon_The_Daybreak_Chronicles.png'),
(58, 'The First Great Magic', 5, 608, 'CRIT DMG 66.2%(14.4%)', 'Parsifal the GreatDMG dealt by Charged Attacks increased by 16~32%. For every party member with the same Elemental Type as the wielder (including the wielder themselves), gain 1 Gimmick stack. For every party member with a different Elemental Type from the wielder, gain 1 Theatrics stack. When the wielder has 1/2/3 or more Gimmick stacks, ATK will be increased by 16/32/48~32/64/96. When the wielder has 1/2/3 or more Theatrics stacks, Movement SPD will be increased by 4/7/10~12/15/18.', 'https://static.wikia.nocookie.net/gensin-impact/images/0/03/Weapon_The_First_Great_Magic.png'),
(59, 'The Unforged', 5, 608, 'ATK 49.6%(10.8%)', 'Golden MajestyIncreases Shield Strength by 20~40%. Scoring hits on opponents increases ATK by 4~8% for 8s. Max 5 stacks. Can only occur once every 0.3s. While protected by a shield, this ATK increase effect is increased by 100%.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/f7/Weapon_The_Unforged.png'),
(60, 'Thundering Pulse', 5, 608, 'CRIT DMG 66.2%(14.4%)', 'Rule By ThunderIncreases ATK by 20~40% and grants the might of the Thunder Emblem. At stack levels 1/2/3, the Thunder Emblem increases Normal Attack DMG by 12/24/40~24/48/80%. The character will obtain 1 stack of Thunder Emblem in each of the following scenarios: Normal Attack deals DMG (stack lasts 5s), casting Elemental Skill (stack lasts 10s); Energy is less than 100% (stack disappears when Energy is full). Each stack\'s duration is calculated independently.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/77/Weapon_Thundering_Pulse.png'),
(61, 'Tome of the Eternal Flow', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'Aeon WaveHP is increased by 16~32%. When current HP increases or decreases, Charged Attack DMG will be increased by 14~30% for 4s. Max 3 stacks, can be triggered once every 0.3s. When you have 3 stacks or refresh a third stack\'s duration, 8~12 Energy will be restored. This Energy restoration effect can be triggered once every 12s.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/91/Weapon_Tome_of_the_Eternal_Flow.png'),
(62, 'Tulaytullah\'s Remembrance', 5, 674, 'CRIT DMG 44.1%(9.6%)', 'Bygone Azure TeardropNormal Attack SPD is increased by 10~20%. After the wielder unleashes an Elemental Skill, Normal Attack DMG will increase by 4.8~9.6% every second for 14s. After this character hits an opponent with a Normal Attack during this duration, Normal Attack DMG will be increased by 9.6~19.2%. This increase can be triggered once every 0.3s. The maximum Normal Attack DMG increase per single duration of the overall effect is 48~96%. The effect will be removed when the wielder leaves the field, and using the Elemental Skill again will reset all DMG buffs.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/fc/Weapon_Tulaytullah%27s_Remembrance.png'),
(63, 'Uraku Misugiri', 5, 542, 'CRIT DMG 88.2%(19.2%)', 'Brocade Bloom, Shrine SwordNormal Attack DMG is increased by 16~32% and Elemental Skill DMG is increased by 24~48%. After a nearby active character deals Geo DMG, the aforementioned effects increase by 100% for 15s. Additionally, the wielder\'s DEF is increased by 20~40%.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/44/Weapon_Uraku_Misugiri.png'),
(64, 'Verdict', 5, 674, 'CRIT Rate 22.1%(4.8%)', 'Many Oaths of Dawn and DuskIncreases ATK by 20~40%. When characters in your party obtain Elemental Shards from Crystallize or trigger Lunar-Crystallize reactions, the equipping character will gain 1 Seal, increasing Elemental Skill DMG by 18~36%. The Seal lasts for 15s, and the equipped may have up to 2 Seals at once. All of the equipper\'s Seals will disappear 0.2s after their Elemental Skill deals DMG. Up to 1 Seal may be obtained every second through the Lunar-Crystallize reaction.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/1d/Weapon_Verdict.png'),
(65, 'Vivid Notions', 5, 674, 'CRIT DMG 44.1%(9.6%)', 'Falling Rainbow\'s WishATK is increased by 28~56%. When you use a Plunging Attack, you will gain the \"Dawn\'s First Hue\" effect: Plunging Attack CRIT DMG is increased by 28~56%. When you use an Elemental Skill or Burst, you will gain the \"Twilight\'s Splendor\" effect: Plunging Attack CRIT DMG is increased by 40~80%. The two effects above each last for 15s, and will be canceled 0.1s after the ground impact hits a target.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/63/Weapon_Vivid_Notions.png'),
(66, 'Vortex Vanquisher', 5, 608, 'ATK 49.6%(10.8%)', 'Golden MajestyIncreases Shield Strength by 20~40%. Scoring hits on opponents increases ATK by 4~8% for 8s. Max 5 stacks. Can only occur once every 0.3s. While protected by a shield, this ATK increase effect is increased by 100%.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/d6/Weapon_Vortex_Vanquisher.png'),
(67, 'Wolf\'s Gravestone', 5, 608, 'ATK 49.6%(10.8%)', 'Wolfish TrackerIncreases ATK by 20~40%. On hit, attacks against opponents with less than 30% HP increase all party members\' ATK by 40~80% for 12s. Can only occur once every 30s.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/4f/Weapon_Wolf%27s_Gravestone.png'),
(68, '\"The Catch\"', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'ShantyIncreases Elemental Burst DMG by 16~32% and Elemental Burst CRIT Rate by 6~12%.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/f5/Weapon_The_Catch.png'),
(69, '\"Ultimate Overlord\'s Mega Magic Sword\"', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'Melussistance!ATK increased by 12~24%. That\'s not all! The support from all Melusines you\'ve helped in Merusea Village fills you with strength! Based on the number of them you\'ve helped, your ATK is increased by up to an additional 12~24%.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/6e/Weapon_Ultimate_Overlord%27s_Mega_Magic_Sword.png'),
(70, 'Akuoumaru', 4, 510, 'ATK 41.3%(9%)', 'Watatsumi WavewalkerFor every point of the entire party\'s combined maximum Energy capacity, the Elemental Burst DMG of the character equipping this weapon is increased by 0.12~0.24%. A maximum of 40~80% increased Elemental Burst DMG can be achieved this way.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/c5/Weapon_Akuoumaru.png'),
(71, 'Alley Hunter', 4, 565, 'ATK 27.6%(6%)', 'Oppidan AmbushWhile the character equipped with this weapon is in the party but not on the field, their DMG increases by 2~4% every second up to a max of 20~40%. When the character is on the field for more than 4s, the aforementioned DMG buff decreases by 4~8% per second until it reaches 0%.', 'https://static.wikia.nocookie.net/gensin-impact/images/0/0a/Weapon_Alley_Hunter.png'),
(72, 'Amenoma Kageuchi', 4, 454, 'ATK 55.1%(12%)', 'Iwakura SuccessionAfter casting an Elemental Skill, gain 1 Succession Seed. This effect can be triggered once every 5s. The Succession Seed lasts for 30s. Up to 3 Succession Seeds may exist simultaneously. After using an Elemental Burst, all Succession Seeds are consumed and after 2s, the character regenerates 6~12 Energy for each seed consumed.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/ea/Weapon_Amenoma_Kageuchi.png'),
(73, 'Ash-Graven Drinking Horn', 4, 510, 'HP 41.3%(9%)', 'Tupac\'s GripWhen an attack hits an opponent, deal AoE DMG equal to 40~80% of Max HP at the target location. This effect can be triggered once every 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/25/Weapon_Ash-Graven_Drinking_Horn.png'),
(74, 'Ballad of the Boundless Blue', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'Azure SkiesWithin 6s after Normal or Charged Attacks hit an opponent, Normal Attack DMG will be increased by 8~16% and Charged Attack DMG will be increased by 6~12%. Max 3 stacks. This effect can be triggered once every 0.3s.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/b5/Weapon_Ballad_of_the_Boundless_Blue.png'),
(75, 'Ballad of the Fjords', 4, 510, 'CRIT Rate 27.6%(6%)', 'Tales of the TundraWhen there are at least 3 different Elemental Types in your party, Elemental Mastery will be increased by 120~240.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/82/Weapon_Ballad_of_the_Fjords.png'),
(76, 'Blackcliff Agate', 4, 510, 'CRIT DMG 55.1%(12%)', 'Press the AdvantageAfter defeating an opponent, ATK is increased by 12~24% for 30s. This effect has a maximum of 3 stacks, and the duration of each stack is independent of the others.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/a6/Weapon_Blackcliff_Agate.png'),
(77, 'Blackcliff Longsword', 4, 565, 'CRIT DMG 36.8%(8%)', 'Press the AdvantageAfter defeating an opponent, ATK is increased by 12~24% for 30s. This effect has a maximum of 3 stacks, and the duration of each stack is independent of the others.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/6f/Weapon_Blackcliff_Longsword.png'),
(78, 'Blackcliff Pole', 4, 510, 'CRIT DMG 55.1%(12%)', 'Press the AdvantageAfter defeating an opponent, ATK is increased by 12~24% for 30s. This effect has a maximum of 3 stacks, and the duration of each stack is independent of the others.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/d5/Weapon_Blackcliff_Pole.png'),
(79, 'Blackcliff Slasher', 4, 510, 'CRIT DMG 55.1%(12%)', 'Press the AdvantageAfter defeating an opponent, ATK is increased by 12~24% for 30s. This effect has a maximum of 3 stacks, and the duration of each stack is independent of the others.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/d7/Weapon_Blackcliff_Slasher.png'),
(80, 'Blackcliff Warbow', 4, 565, 'CRIT DMG 36.8%(8%)', 'Press the AdvantageAfter defeating an opponent, ATK is increased by 12~24% for 30s. This effect has a maximum of 3 stacks, and the duration of each stack is independent of the others.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/b8/Weapon_Blackcliff_Warbow.png'),
(81, 'Blackmarrow Lantern', 4, 454, 'Elemental Mastery 221(48)', 'Token of CovenantBloom DMG is increased by 48~96%, and Lunar-Bloom DMG is increased by 12~24%. Moonsign: Ascendant Gleam: Lunar-Bloom DMG is increased by an additional 12~24%.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/c7/Weapon_Blackmarrow_Lantern.png'),
(82, 'Calamity of Eshu', 4, 565, 'ATK 27.6%(6%)', 'Diffusing BoundaryWhile characters are protected by a Shield, DMG dealt by Normal and Charged Attacks is increased by 20~40%, and Normal and Charged Attack CRIT Rate is increased by 8~16%.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/7b/Weapon_Calamity_of_Eshu.png'),
(83, 'Chain Breaker', 4, 565, 'ATK 27.6%(6%)', 'Flower—Feather SongFor every party member from Natlan or who has a different Elemental Type from the equipping character, the equipping character gains 4.8~9.6% increased ATK. When there are no less than 3 of the aforementioned characters, the equipping character gains 24~48 Elemental Mastery.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/7a/Weapon_Chain_Breaker.png'),
(84, 'Cinnabar Spindle', 4, 454, 'DEF 69.0%(15%)', 'Spotless HeartElemental Skill DMG is increased by 40~80% of DEF. The effect will be triggered no more than once every 1.5s and will be cleared 0.1s after the Elemental Skill deals DMG.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/dc/Weapon_Cinnabar_Spindle.png'),
(85, 'Cloudforged', 4, 510, 'Elemental Mastery 165(36)', 'Crag-Chiseled ForgeAfter Elemental Energy is decreased, the equipping character\'s Elemental Mastery will increase by 40~80 for 18s. Max 2 stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/f8/Weapon_Cloudforged.png'),
(86, 'Compound Bow', 4, 454, 'Physical DMG Bonus 69.0%(15%)', 'Infusion ArrowNormal Attack and Charged Attack hits increase ATK by 4~8% and Normal ATK SPD by 1.2~2.4% for 6s. Max 4 stacks. Can only occur once every 0.3s.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/32/Weapon_Compound_Bow.png'),
(87, 'Crescent Pike', 4, 565, 'Physical DMG Bonus 34.5%(7.5%)', 'Infusion NeedleAfter picking up an Elemental Orb/Particle, Normal and Charged Attacks deal an additional 20~40% ATK as DMG for 5s.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/4c/Weapon_Crescent_Pike.png'),
(88, 'Dawning Frost', 4, 510, 'CRIT DMG 55.1%(12%)', 'Nocturnal DreamsFor 10s after a Charged Attack hits an opponent, Elemental Mastery is increased by 72~144. For 10s after an Elemental Skill hits an opponent. Elemental Mastery is increased by 48~96.', 'https://static.wikia.nocookie.net/gensin-impact/images/0/0d/Weapon_Dawning_Frost.png'),
(89, 'Deathmatch', 4, 454, 'CRIT Rate 36.8%(8%)', 'GladiatorIf there are at least 2 opponents nearby, ATK is increased by 16~32% and DEF is increased by 16~32%. If there are fewer than 2 opponents nearby, ATK is increased by 24~48%.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/69/Weapon_Deathmatch.png'),
(90, 'Dialogues of the Desert Sages', 4, 510, 'HP 41.3%(9%)', 'Principle of EquilibriumWhen the wielder performs healing, restore 8~16 Energy. This effect can be triggered once every 10s and can occur even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/ea/Weapon_Dialogues_of_the_Desert_Sages.png'),
(91, 'Dodoco Tales', 4, 454, 'ATK 55.1%(12%)', 'Dodoventure!Normal Attack hits on opponents increase Charged Attack DMG by 16~32% for 6s. Charged Attack hits on opponents increase ATK by 8~16% for 6s.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/51/Weapon_Dodoco_Tales.png'),
(92, 'Dragon\'s Bane', 4, 454, 'Elemental Mastery 221(48)', 'Bane of Flame and WaterIncreases DMG against opponents affected by Hydro or Pyro by 20~36%.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/24/Weapon_Dragon%27s_Bane.png'),
(93, 'Dragonspine Spear', 4, 454, 'Physical DMG Bonus 69.0%(15%)', 'Frost BurialHitting an opponent with Normal and Charged Attacks has a 60~100% chance of forming and dropping an Everfrost Icicle above them, dealing 80~140% AoE ATK DMG. Opponents affected by Cryo are dealt 200~360% ATK DMG instead by the icicle. Can only occur once every 10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/1a/Weapon_Dragonspine_Spear.png'),
(94, 'Earth Shaker', 4, 565, 'ATK 27.6%(6%)', 'Oath of Qhapaq NanAfter a party member triggers a Pyro-related reaction, the equipping character\'s Elemental Skill DMG is increased by 16~32% for 8s. This effect can be triggered even when the triggering party member is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/78/Weapon_Earth_Shaker.png'),
(95, 'End of the Line', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'Net SnapperTriggers the Flowrider effect after using an Elemental Skill, dealing 80~160% ATK as AoE DMG upon hitting an opponent with an attack. Flowrider will be removed after 15s or after causing 3 instances of AoE DMG. Only 1 instance of AoE DMG can be caused every 2s in this way. Flowrider can be triggered once every 12s.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/71/Weapon_End_of_the_Line.png'),
(96, 'Etherlight Spindlelute', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'Last SingerFor 20s after using an Elemental Skill, the equipping character\'s Elemental Mastery is increased by 100~200.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/c3/Weapon_Etherlight_Spindlelute.png'),
(97, 'Eye of Perception', 4, 454, 'ATK 55.1%(12%)', 'EchoNormal and Charged Attacks have a 50% chance to fire a Bolt of Perception, dealing 240~360% ATK as DMG. This bolt can bounce between opponents a maximum of 4 times. This effect can occur once every 12~8s.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/6c/Weapon_Eye_of_Perception.png'),
(98, 'Fading Twilight', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'Radiance of the DeepsHas three states, Evengleam, Afterglow, and Dawnblaze, which increase DMG dealt by 6/10/14~12/20/28 respectively. When attacks hit opponents, this weapon will switch to the next state. This weapon can change states once every 7s. The character equipping this weapon can still trigger the state switch while not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/2b/Weapon_Fading_Twilight.png'),
(99, 'Favonius Codex', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'WindfallCRIT hits have a 60~100% chance to generate a small amount of Elemental Particles, which will regenerate 6 Energy for the character. Can only occur once every 12~6s.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/36/Weapon_Favonius_Codex.png'),
(100, 'Favonius Greatsword', 4, 454, 'Energy Recharge 61.3%(13.3%)', 'WindfallCRIT hits have a 60~100% chance to generate a small amount of Elemental Particles, which will regenerate 6 Energy for the character. Can only occur once every 12~6s.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/9c/Weapon_Favonius_Greatsword.png'),
(101, 'Favonius Lance', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'WindfallCRIT Hits have a 60~100% chance to generate a small amount of Elemental Particles, which will regenerate 6 Energy for the character. Can only occur once every 12~6s.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/57/Weapon_Favonius_Lance.png'),
(102, 'Favonius Sword', 4, 454, 'Energy Recharge 61.3%(13.3%)', 'WindfallCRIT hits have a 60~100% chance to generate a small amount of Elemental Particles, which will regenerate 6 Energy for the character. Can only occur once every 12~6s.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/90/Weapon_Favonius_Sword.png'),
(103, 'Favonius Warbow', 4, 454, 'Energy Recharge 61.3%(13.3%)', 'WindfallCRIT hits have a 60~100% chance to generate a small amount of Elemental Particles, which will regenerate 6 Energy for the character. Can only occur once every 12~6s.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/85/Weapon_Favonius_Warbow.png'),
(104, 'Festering Desire', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'Undying AdmirationIncreases Elemental Skill DMG by 16~32% and Elemental Skill CRIT Rate by 6~12%.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/70/Weapon_Festering_Desire.png'),
(105, 'Finale of the Deep', 4, 565, 'ATK 27.6%(6%)', 'An End SublimeWhen using an Elemental Skill, ATK will be increased by 12~24% for 15s, and a Bond of Life worth 25% of Max HP will be granted. This effect can be triggered once every 10s. When the Bond of Life is cleared, a maximum of 150~300 ATK will be gained based on 2.4~4.8% of the total amount of the Life Bond cleared, lasting for 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/5a/Weapon_Finale_of_the_Deep.png'),
(106, 'Flame-Forged Insight', 4, 510, 'Elemental Mastery 165(36)', 'Mind in BloomWhen Electro-Charged, Lunar-Charged, Bloom, Lunar-Bloom, Crystallize or Lunar-Crystallize is triggered, restore 12~24 Elemental Energy and increase Elemental Mastery by 60~120 for 15 seconds. This effect can be triggered once every 15s and can be triggered even when the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/45/Weapon_Flame-Forged_Insight.png');
INSERT INTO `weapons` (`id`, `name`, `rarity`, `base_atk`, `substat`, `passive`, `image`) VALUES
(107, 'Fleuve Cendre Ferryman', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'IronboneIncreases Elemental Skill CRIT Rate by 8~16%. Additionally, increases Energy Recharge by 16~32% for 5s after using an Elemental Skill.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/7e/Weapon_Fleuve_Cendre_Ferryman.png'),
(108, 'Flower-Wreathed Feathers', 4, 510, 'ATK 41.3%(9%)', 'Inflorescence UnattainableDecreases Gliding Stamina consumption by 15%. When using Aimed Shots, the DMG dealt by Charged Attacks increases by 6~12% every 0.5s. This effect can stack up to 6 times and will be removed 10s after leaving Aiming Mode.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/1f/Weapon_Flower-Wreathed_Feathers.png'),
(109, 'Flowing Purity', 4, 565, 'ATK 27.6%(6%)', 'Unfinished MasterpieceWhen using an Elemental Skill, All Elemental DMG Bonus will be increased by 8~16% for 15s, and a Bond of Life worth 24% of Max HP will be granted. This effect can be triggered once every 10s. When the Bond of Life is cleared, every 1,000 HP cleared in the process will provide 2~4% All Elemental DMG Bonus, up to a maximum of 12~24%. This effect lasts 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/0/01/Weapon_Flowing_Purity.png'),
(110, 'Flute of Ezpitzal', 4, 454, 'DEF 69.0%(15%)', 'Smoke-and-Mirror MysteryUsing an Elemental Skill increases DEF by 16~32% for 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/31/Weapon_Flute_of_Ezpitzal.png'),
(111, 'Footprint of the Rainbow', 4, 510, 'DEF 51.7%(11.3%)', 'Pact of Flowing SpringsUsing an Elemental Skill increases DEF by 16~32% for 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/d6/Weapon_Footprint_of_the_Rainbow.png'),
(112, 'Forest Regalia', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'Forest SanctuaryAfter triggering Burning, Quicken, Aggravate, Spread, Bloom, Lunar-Bloom, Hyperbloom, or Burgeon, a Leaf of Consciousness will be created around the character for a maximum of 10s. When picked up, the Leaf will grant the character 60~120 Elemental Mastery for 12s. Only 1 Leaf can be generated this way every 20s. This effect can still be triggered if the character is not on the field. The Leaf of Consciousness\' effect cannot stack.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/51/Weapon_Forest_Regalia.png'),
(113, 'Frostbearer', 4, 510, 'ATK 41.3%(9%)', 'Frost BurialHitting an opponent with Normal and Charged Attacks has a 60~100% chance of forming and dropping an Everfrost Icicle above them, dealing 80~140% AoE ATK DMG. Opponents affected by Cryo are dealt 200~360% ATK DMG instead by the icicle. Can only occur once every 10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/1c/Weapon_Frostbearer.png'),
(114, 'Fruit of Fulfillment', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'Full CircleObtain the \"Wax and Wane\" effect after an Elemental Reaction is triggered, gaining 24~36 Elemental Mastery while losing 5% ATK. For every 0.3s, 1 stack of Wax and Wane can be gained. Max 5 stacks. For every 6s that go by without an Elemental Reaction being triggered, 1 stack will be lost. This effect can be triggered even when the character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/98/Weapon_Fruit_of_Fulfillment.png'),
(115, 'Fruitful Hook', 4, 565, 'ATK 27.6%(6%)', 'The Weight of Falling BranchesIncrease Plunging Attack CRIT Rate by 16~32%; After a Plunging Attack hits an opponent, Normal, Charged, and Plunging Attack DMG increased by 16~32% for 10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/bb/Weapon_Fruitful_Hook.png'),
(116, 'Hakushin Ring', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'Sakura SaiguuAfter the character equipped with this weapon triggers an Electro elemental reaction, nearby party members of an Elemental Type involved in the elemental reaction receive a 10~20% Elemental DMG Bonus for their element, lasting 6s. Elemental Bonuses gained in this way cannot be stacked.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/ee/Weapon_Hakushin_Ring.png'),
(117, 'Hamayumi', 4, 454, 'ATK 55.1%(12%)', 'Full DrawIncreases Normal Attack DMG by 16~32% and Charged Attack DMG by 12~24%. When the equipping character\'s Energy reaches 100%, this effect is increased by 100%.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/d9/Weapon_Hamayumi.png'),
(118, 'Ibis Piercer', 4, 565, 'ATK 27.6%(6%)', 'Secret Wisdom\'s FavorThe character\'s Elemental Mastery will increase by 40~80 within 6s after Charged Attacks hit opponents. Max 2 stacks. This effect can be triggered once every 0.5s.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/ce/Weapon_Ibis_Piercer.png'),
(119, 'Iron Sting', 4, 510, 'Elemental Mastery 165(36)', 'Infusion StingerDealing Elemental DMG increases all DMG by 6~12% for 6s. Max 2 stacks. Can only occur once every 1s.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/35/Weapon_Iron_Sting.png'),
(120, 'Kagotsurube Isshin', 4, 510, 'ATK 41.3%(9%)', 'Isshin Art ClarityWhen a Normal, Charged, or Plunging Attack hits an opponent, it will whip up a Hewing Gale, dealing AoE DMG equal to 180% of ATK and increasing ATK by 15% for 8s. This effect can be triggered once every 8s.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/96/Weapon_Kagotsurube_Isshin.png'),
(121, 'Katsuragikiri Nagamasa', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'Samurai ConductIncreases Elemental Skill DMG by 6~12%. After Elemental Skill hits an opponent, the character loses 3 Energy but regenerates 3~5 Energy every 2s for the next 6s. This effect can occur once every 10s. Can be triggered even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/2e/Weapon_Katsuragikiri_Nagamasa.png'),
(122, 'King\'s Squire', 4, 454, 'ATK 55.1%(12%)', 'Labyrinth Lord\'s InstructionObtain the Teachings of the Forest effect when unleashing Elemental Skills and Elemental Burst, increasing Elemental Mastery by 60~140 for 12s. This effect will be removed when switching characters. When the Teachings of the Forest effect ends or is removed, it will deal 100~180% of ATK as DMG to 1 nearby opponent. The Teachings of the Forest effect can be triggered once every 20s.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/a2/Weapon_King%27s_Squire.png'),
(123, 'Kitain Cross Spear', 4, 565, 'Elemental Mastery 110(24)', 'Samurai ConductIncreases Elemental Skill DMG by 6~12%. After Elemental Skill hits an opponent, the character loses 3 Energy but regenerates 3~5 Energy every 2s for the next 6s. This effect can occur once every 10s. Can be triggered even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/13/Weapon_Kitain_Cross_Spear.png'),
(124, 'Lion\'s Roar', 4, 510, 'ATK 41.3%(9%)', 'Bane of Fire and ThunderIncreases DMG against enemies affected by Pyro or Electro by 20~36%.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/e6/Weapon_Lion%27s_Roar.png'),
(125, 'Lithic Blade', 4, 510, 'ATK 41.3%(9%)', 'Lithic Axiom: UnityFor every character in the party who hails from Liyue, the character who equips this weapon gains 7~11% ATK increase and 3~7% CRIT Rate increase. This effect stacks up to 4 times.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/3a/Weapon_Lithic_Blade.png'),
(126, 'Lithic Spear', 4, 565, 'ATK 27.6%(6%)', 'Lithic Axiom: UnityFor every character in the party who hails from Liyue, the character who equips this weapon gains 7~11% ATK increase and a 3~7% CRIT Rate increase. This effect stacks up to 4 times.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/2a/Weapon_Lithic_Spear.png'),
(127, 'Luxurious Sea-Lord', 4, 454, 'ATK 55.1%(12%)', 'Oceanic VictoryIncreases Elemental Burst DMG by 12~24%. When Elemental Burst hits opponents, there is a 100% chance of summoning a huge onrush of tuna that deals 100~200% ATK as AoE DMG. This effect can occur once every 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/ab/Weapon_Luxurious_Sea-Lord.png'),
(128, 'Mailed Flower', 4, 565, 'Elemental Mastery 110(24)', 'Whispers of Wind and FlowerWithin 8s after the character\'s Elemental Skill hits an opponent or the character triggers an Elemental Reaction, their ATK and Elemental Mastery will be increased by 12~24% and 48~96 respectively.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/c7/Weapon_Mailed_Flower.png'),
(129, 'Makhaira Aquamarine', 4, 510, 'Elemental Mastery 165(36)', 'Desert PavilionThe following effect will trigger every 10s: The equipping character will gain 24~48% of their Elemental Mastery as bonus ATK for 12s, with nearby party members gaining 30% of this buff for the same duration. Multiple instances of this weapon can allow this buff to stack. This effect will still trigger even if the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/90/Weapon_Makhaira_Aquamarine.png'),
(130, 'Mappa Mare', 4, 565, 'Elemental Mastery 110(24)', 'Infusion ScrollTriggering an Elemental reaction grants a 8~16% Elemental DMG Bonus for 10s. Max 2 stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/4d/Weapon_Mappa_Mare.png'),
(131, 'Master Key', 4, 454, 'Energy Recharge 61.3%(13.3%)', 'Fall Into PlaceUpon causing an Elemental Reaction, increases Elemental Mastery by 60~120 for 12s. Moonsign: Ascendant Gleam: Elemental Mastery from this effect is further increased by 60~120. This effect can be triggered even if the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/82/Weapon_Master_Key.png'),
(132, 'Missive Windspear', 4, 510, 'ATK 41.3%(9%)', 'The Wind UnattainedWithin 10s after an Elemental Reaction is triggered, ATK is increased by 12~24% and Elemental Mastery is increased by 48~96.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/9b/Weapon_Missive_Windspear.png'),
(133, 'Mitternachts Waltz', 4, 510, 'Physical DMG Bonus 51.7%(11.3%)', 'Evernight DuetNormal Attack hits on opponents increase Elemental Skill DMG by 20~40% for 5s. Elemental Skill hits on opponents increase Normal Attack DMG by 20~40% for 5s.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/77/Weapon_Mitternachts_Waltz.png'),
(134, 'Moonpiercer', 4, 565, 'Elemental Mastery 110(24)', 'Stillwood MoonshadowAfter triggering Burning, Quicken, Aggravate, Spread, Bloom, Lunar-Bloom, Hyperbloom, or Burgeon, a Leaf of Revival will be created around the character for a maximum of 10s. When picked up, the Leaf will grant the character 16~32% ATK for 12s. Only 1 Leaf can be generated this way every 20s. This effect can still be triggered if the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/a4/Weapon_Moonpiercer.png'),
(135, 'Moonweaver\'s Dawn', 4, 565, 'ATK 27.6%(6%)', 'Secret Silver\'s TestamentIncreases Elemental Burst DMG by 20~40%. When the equipping character\'s Energy Capacity does not exceed 60/40, their Elemental Burst DMG is increased by an additional 16/28~32/56%.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/f1/Weapon_Moonweaver%27s_Dawn.png'),
(136, 'Mountain-Bracing Bolt', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'Hope Beyond the PeaksDecreases Climbing Stamina Consumption by 15% and increases Elemental Skill DMG by 12~24%. Also, after other nearby party members use Elemental Skills, the equipping character\'s Elemental Skill DMG will also increase by 12~24% for 8s.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/66/Weapon_Mountain-Bracing_Bolt.png'),
(137, 'Mouun\'s Moon', 4, 565, 'ATK 27.6%(6%)', 'Watatsumi WavewalkerFor every point of the entire party\'s combined maximum Energy capacity, the Elemental Burst DMG of the character equipping this weapon is increased by 0.12~0.24%. A maximum of 40~80% increased Elemental Burst DMG can be achieved this way.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/42/Weapon_Mouun%27s_Moon.png'),
(138, 'Oathsworn Eye', 4, 565, 'ATK 27.6%(6%)', 'People of the Faltering LightIncreases Energy Recharge by 24~48% for 10s after using an Elemental Skill.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/af/Weapon_Oathsworn_Eye.png'),
(139, 'Portable Power Saw', 4, 454, 'HP 55.1%(12%)', 'Sea ShantyWhen the wielder is healed or heals others, they will gain a Stoic\'s Symbol that lasts 30s, up to a maximum of 3 Symbols. When using their Elemental Skill or Burst, all Symbols will be consumed and the Roused effect will be granted for 10s. For each Symbol consumed, gain 40~80 Elemental Mastery, and 2s after the effect occurs, 2~4 Energy per Symbol consumed will be restored for said character. The Roused effect can be triggered once every 15s, and Symbols can be gained even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/49/Weapon_Portable_Power_Saw.png'),
(140, 'Predator', 4, 510, 'ATK 41.3%(9%)', 'Strong StrikeEffective only on the following platform:\"PlayStation Network\"Dealing Cryo DMG to opponents increases this character\'s Normal and Charged Attack DMG by 10% for 6s. This effect can have a maximum of 2 stacks. Additionally, when Aloy equips Predator, ATK is increased by 66.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/2e/Weapon_Predator.png'),
(141, 'Prospector\'s Drill', 4, 565, 'ATK 27.6%(6%)', 'Masons\' DittyWhen the wielder is healed or heals others, they will gain a Unity\'s Symbol that lasts 30s, up to a maximum of 3 Symbols. When using their Elemental Skill or Burst, all Symbols will be consumed and the Struggle effect will be granted for 10s. For each Symbol consumed, gain 3~7% ATK and 7~13% All Elemental DMG Bonus. The Struggle effect can be triggered once every 15s, and Symbols can be gained even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/b1/Weapon_Prospector%27s_Drill.png'),
(142, 'Prospector\'s Shovel', 4, 510, 'ATK 41.3%(9%)', 'Swift and SureElectro-Charged DMG is increased by 48~96%, and Lunar-Charged DMG is increased by 12~24%. Moonsign: Ascendant Gleam: Lunar-Charged DMG is increased by an additional 12~24%.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/fc/Weapon_Prospector%27s_Shovel.png'),
(143, 'Prototype Amber', 4, 510, 'HP 41.3%(9%)', 'GildingUsing an Elemental Burst regenerates 4~6 Energy every 2s for 6s. All party members will regenerate 4~6% HP every 2s for this duration.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/2a/Weapon_Prototype_Amber.png'),
(144, 'Prototype Archaic', 4, 565, 'ATK 27.6%(6%)', 'CrushOn hit, Normal or Charged Attacks have a 50% chance to deal an additional 240~480% ATK DMG to opponents within a small AoE. Can only occur once every 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/ab/Weapon_Prototype_Archaic.png'),
(145, 'Prototype Crescent', 4, 510, 'ATK 41.3%(9%)', 'UnreturningCharged Attack hits on weak points increase Movement SPD by 10% and ATK by 36~72% for 10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/43/Weapon_Prototype_Crescent.png'),
(146, 'Prototype Rancour', 4, 565, 'Physical DMG Bonus 34.5%(7.5%)', 'Smashed StoneOn hit, Normal or Charged Attacks increase ATK and DEF by 4~8% for 6s. Max 4 stacks. This effect can only occur once every 0.3s.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/ef/Weapon_Prototype_Rancour.png'),
(147, 'Prototype Starglitter', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'Magic AffinityAfter using an Elemental Skill, increases Normal and Charged Attack DMG by 8~16% for 12s. Max 2 stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/7e/Weapon_Prototype_Starglitter.png'),
(148, 'Rainbow Serpent\'s Rain Bow', 4, 510, 'Energy Recharge 45.9%(10.0%)', 'Astral Whispers Beyond the Sacred ThroneATK is increased by 28~56% for 8s after the equipping character\'s attacks hit an opponent while the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/6e/Weapon_Rainbow_Serpent%27s_Rain_Bow.png'),
(149, 'Rainslasher', 4, 510, 'Elemental Mastery 165(36)', 'Bane of Storm and TideIncreases DMG against opponents affected by Hydro or Electro by 20~36%.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/d4/Weapon_Rainslasher.png'),
(150, 'Range Gauge', 4, 565, 'ATK 27.6%(6%)', 'Masons\' DittyWhen the wielder is healed or heals others, they will gain a Unity\'s Symbol that lasts 30s, up to a maximum of 3 Symbols. When using their Elemental Skill or Burst, all Symbols will be consumed and the Struggle effect will be granted for 10s. For each Symbol consumed, gain 3~7% ATK and 7~13% All Elemental DMG Bonus. The Struggle effect can be triggered once every 15s, and Symbols can be gained even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/11/Weapon_Range_Gauge.png'),
(151, 'Rightful Reward', 4, 565, 'HP 27.6%(6%)', 'Tip of the SpearWhen the wielder is healed, restore 8~16 Energy. This effect can be triggered once every 10s, and can occur even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/8d/Weapon_Rightful_Reward.png'),
(152, 'Ring of Yaxche', 4, 510, 'HP 41.3%(9%)', 'Echoes of the Plentiful LandUsing an Elemental Skill grants the Jade-Forged Crown effect: Every 1,000 Max HP will increase the Normal Attack DMG dealt by the equipping character by 0.6~1% for 10s. Normal Attack DMG can be increased this way by a maximum of 16~32%.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/45/Weapon_Ring_of_Yaxche.png'),
