(154, 'Royal Greatsword', 4, 565, 'ATK 27.6%(6%)', 'FocusUpon dealing damage to an opponent, increases CRIT Rate by 8~16%. Max 5 stacks. A CRIT hit removes all existing stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/bf/Weapon_Royal_Greatsword.png'),
(155, 'Royal Grimoire', 4, 565, 'ATK 27.6%(6%)', 'FocusUpon dealing damage to an opponent, increases CRIT Rate by 8~16%. Max 5 stacks. A CRIT hit removes all existing stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/99/Weapon_Royal_Grimoire.png'),
(156, 'Royal Longsword', 4, 510, 'ATK 41.3%(9%)', 'FocusUpon dealing damage to an opponent, increases CRIT Rate by 8~16%. Max 5 stacks. A CRIT hit removes all existing stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/cd/Weapon_Royal_Longsword.png'),
(157, 'Royal Spear', 4, 565, 'ATK 27.6%(6%)', 'FocusUpon dealing damage to an opponent, increases CRIT Rate by 8~16%. Max 5 stacks. A CRIT hit removes all existing stacks.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/fd/Weapon_Royal_Spear.png'),
(158, 'Rust', 4, 510, 'ATK 41.3%(9%)', 'Rapid FiringIncreases Normal Attack DMG by 40~80% but decreases Charged Attack DMG by 10%.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/1c/Weapon_Rust.png'),
(159, 'Sacrificer\'s Staff', 4, 620, 'CRIT Rate 9.2%(2.0%)', 'Untainted DesireFor 6s after an Elemental Skill hits an opponent, ATK is increased by 8~16% and Energy Recharge is increased by 6~12%. Max 3 stacks. This effect can be triggered even when the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/40/Weapon_Sacrificer%27s_Staff.png'),
(160, 'Sacrificial Bow', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'ComposedAfter dealing damage to an opponent with an Elemental Skill, the skill has a 40~80% chance to end its own CD. Can only occur once every 30~16s.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/ec/Weapon_Sacrificial_Bow.png'),
(161, 'Sacrificial Fragments', 4, 454, 'Elemental Mastery 221(48)', 'ComposedAfter dealing damage to an opponent with an Elemental Skill, the skill has a 40~80% chance to end its own CD. Can only occur once every 30~16s.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/6c/Weapon_Sacrificial_Fragments.png'),
(162, 'Sacrificial Greatsword', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'ComposedAfter dealing damage to an opponent with an Elemental Skill, the skill has a 40~80% chance to end its own CD. Can only occur once every 30~16s.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/17/Weapon_Sacrificial_Greatsword.png'),
(163, 'Sacrificial Jade', 4, 454, 'CRIT Rate 36.8%(8%)', 'Jade CirculationWhen not on the field for more than 5s, Max HP will be increased by 32~64% and Elemental Mastery will be increased by 40~80. These effects will be canceled after the wielder has been on the field for 10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/86/Weapon_Sacrificial_Jade.png'),
(164, 'Sacrificial Sword', 4, 454, 'Energy Recharge 61.3%(13.3%)', 'ComposedAfter dealing damage to an opponent with an Elemental Skill, the skill has a 40~80% chance to end its own CD. Can only occur once every 30~16s.', 'https://static.wikia.nocookie.net/gensin-impact/images/a/a0/Weapon_Sacrificial_Sword.png'),
(165, 'Sapwood Blade', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'Forest SanctuaryAfter triggering Burning, Quicken, Aggravate, Spread, Bloom, Lunar-Bloom, Hyperbloom, or Burgeon, a Leaf of Consciousness will be created around the character for a maximum of 10s. When picked up, the Leaf will grant the character 60~120 Elemental Mastery for 12s. Only 1 Leaf can be generated this way every 20s. This effect can still be triggered if the character is not on the field. The Leaf of Consciousness\' effect cannot stack.', 'https://static.wikia.nocookie.net/gensin-impact/images/0/00/Weapon_Sapwood_Blade.png'),
(166, 'Scion of the Blazing Sun', 4, 565, 'CRIT Rate 18.4%(4%)', 'The Way of SunfireAfter a Charged Attack hits an opponent, a Sunfire Arrow will descend upon the opponent hit, dealing 60~120% ATK as DMG, and applying the Heartsearer effect to the opponent damaged by said Arrow for 10s. Opponents affected by Heartsearer take 28~56% more Charged Attack DMG from the wielder. A Sunfire Arrow can be triggered once every 10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/83/Weapon_Scion_of_the_Blazing_Sun.png'),
(167, 'Sequence of Solitude', 4, 510, 'HP 41.3%(9%)', 'Silent TriggerWhen an attack hits an opponent, deal AoE DMG equal to 40~80% of Max HP at the target location. This effect can be triggered once every 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/d3/Weapon_Sequence_of_Solitude.png'),
(168, 'Serenity\'s Call', 4, 454, 'Energy Recharge 61.3%(13.3%)', 'Solemn SilenceUpon causing an Elemental Reaction, increases Max HP by 16~32% for 12s. Moonsign: Ascendant Gleam: Max HP from this effect is further increased by 16~32%. This effect can be triggered even if the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/fe/Weapon_Serenity%27s_Call.png'),
(169, 'Serpent Spine', 4, 510, 'CRIT Rate 27.6%(6%)', 'WavesplitterEvery 4s a character is on the field, they will deal 6~10% more DMG and take 3~2% more DMG. This effect has a maximum of 5 stacks and will not be reset if the character leaves the field, but will be reduced by 1 stack when the character takes DMG.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/88/Weapon_Serpent_Spine.png'),
(170, 'Snare Hook', 4, 454, 'Energy Recharge 61.3%(13.3%)', 'Phantom FlashUpon causing an Elemental Reaction, increases Elemental Mastery by 60~120 for 12s. Moonsign: Ascendant Gleam: Elemental Mastery from this effect is further increased by 60~120. This effect can be triggered even if the equipping character is off-field.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/c8/Weapon_Snare_Hook.png'),
(171, 'Snow-Tombed Starsilver', 4, 565, 'Physical DMG Bonus 34.5%(7.5%)', 'Frost BurialHitting an opponent with Normal and Charged Attacks has a 60~100% chance of forming and dropping an Everfrost Icicle above them, dealing AoE DMG equal to 80~140% of ATK. Opponents affected by Cryo are instead dealt DMG equal to 200~360% of ATK. Can only occur once every 10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/49/Weapon_Snow-Tombed_Starsilver.png'),
(172, 'Solar Pearl', 4, 510, 'CRIT Rate 27.6%(6%)', 'Solar ShineNormal Attack hits increase Elemental Skill and Elemental Burst DMG by 20~40% for 6s. Likewise, Elemental Skill or Elemental Burst hits increase Normal Attack DMG by 20~40% for 6s.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/fc/Weapon_Solar_Pearl.png'),
(173, 'Song of Stillness', 4, 510, 'ATK 41.3%(9%)', 'Benthic PulseAfter the wielder is healed, they will deal 16~32% more DMG for 8s. This can be triggered even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/bd/Weapon_Song_of_Stillness.png'),
(174, 'Sturdy Bone', 4, 565, 'ATK 27.6%(6%)', 'Trapper\'s PrideSprint or Alternate Sprint Stamina Consumption decreased by 15%. Additionally, after using Sprint or Alternate Sprint, Normal Attack DMG is increased by 16~32% of ATK. This effect expires after triggering 18 times or 7s.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/ff/Weapon_Sturdy_Bone.png'),
(175, 'Sword of Descension', 4, 440, 'ATK 35.2%(7.7%)', 'DescensionEffective only on the following platform:\"PlayStation Network\"Hitting enemies with Normal or Charged Attacks grants a 50% chance to deal 200% ATK as DMG in a small AoE. This effect can only occur once every 10s. Additionally, if the Traveler equips the Sword of Descension, their ATK is increased by 66.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/17/Weapon_Sword_of_Descension.png'),
(176, 'Sword of Narzissenkreuz', 4, 510, 'ATK 41.3%(9%)', 'Hero\'s BladeWhen the equipping character does not have an Arkhe: When Normal Attacks, Charged Attacks, or Plunging Attacks strike, a Pneuma or Ousia energy blast will be unleashed, dealing 160~320% of ATK as DMG. This effect can be triggered once every 12s. The energy blast type is determined by the current type of the Sword of Narzissenkreuz.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/1f/Weapon_Sword_of_Narzissenkreuz_Pneuma.png'),
(177, 'Talking Stick', 4, 565, 'CRIT Rate 18.4%(4%)', '\"The Silver Tongue\"ATK will be increased by 16~32% for 15s after being affected by Pyro. This effect can be triggered once every 12s. All Elemental DMG Bonus will be increased by 12~24% for 15s after being affected by Hydro, Cryo, Electro, or Dendro. This effect can be triggered once every 12s.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/28/Weapon_Talking_Stick.png'),
(178, 'Tamayuratei no Ohanashi', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'Busybody\'s Running LightIncrease ATK by 20~40% and Movement SPD by 10% for 10s when using an Elemental Skill.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/53/Weapon_Tamayuratei_no_Ohanashi.png'),
(179, 'The Alley Flash', 4, 620, 'Elemental Mastery 55(12)', 'Itinerant HeroIncreases DMG dealt by the character equipping this weapon by 12~24%. Taking DMG disables this effect for 5s.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/83/Weapon_The_Alley_Flash.png'),
(180, 'The Bell', 4, 510, 'HP 41.3%(9%)', 'Rebellious GuardianTaking DMG generates a shield which absorbs DMG up to 20~32% of max HP. This shield lasts for 10s or until broken, and can only be triggered once every 45s. While protected by a shield, the character gains 12~24% increased DMG.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/6e/Weapon_The_Bell.png'),
(181, 'The Black Sword', 4, 510, 'CRIT Rate 27.6%(6%)', 'JusticeIncreases DMG dealt by Normal and Charged Attacks by 20~40%.Additionally, regenerates 60~100% of ATK as HP when Normal and Charged Attacks score a CRIT Hit. This effect can occur once every 5s.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/cf/Weapon_The_Black_Sword.png'),
(182, 'The Dockhand\'s Assistant', 4, 510, 'HP 41.3%(9%)', 'Sea ShantyWhen the wielder is healed or heals others, they will gain a Stoic\'s Symbol that lasts 30s, up to a maximum of 3 Symbols. When using their Elemental Skill or Burst, all Symbols will be consumed and the Roused effect will be granted for 10s. For each Symbol consumed, gain 40~80 Elemental Mastery, and 2s after the effect occurs, 2~4 Energy per Symbol consumed will be restored for said character. The Roused effect can be triggered once every 15s, and Symbols can be gained even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/eb/Weapon_The_Dockhand%27s_Assistant.png'),
(183, 'The Flute', 4, 510, 'ATK 41.3%(9%)', 'ChordNormal or Charged Attacks grant a Harmonic on hits. Gaining 5 Harmonics triggers the power of music and deals 100~200% ATK DMG to surrounding enemies. Harmonics last up to 30s, and a maximum of 1 can be gained every 0.5s.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/63/Weapon_The_Flute.png'),
(184, 'The Stringless', 4, 510, 'Elemental Mastery 165(36)', 'Arrowless SongIncreases Elemental Skill and Elemental Burst DMG by 24~48%.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/71/Weapon_The_Stringless.png'),
(185, 'The Viridescent Hunt', 4, 510, 'CRIT Rate 27.6%(6%)', 'Verdant WindUpon hit, Normal and Aimed Shot Attacks have a 50% chance to generate a Cyclone, which will continuously attract surrounding opponents, dealing 40~80% of ATK as DMG to these opponents every 0.5s for 4s. This effect can only occur once every 14~10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/ff/Weapon_The_Viridescent_Hunt.png'),
(186, 'The Widsith', 4, 510, 'CRIT DMG 55.1%(12%)', 'DebutWhen a character takes the field, they will gain a random theme song for 10s. This can only occur once every 30s. Recitative: ATK is increased by 60~120%. Aria: Increases all Elemental DMG by 48~96%. Interlude: Elemental Mastery is increased by 240~480.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/f0/Weapon_The_Widsith.png'),
(187, 'Tidal Shadow', 4, 510, 'ATK 41.3%(9%)', 'White Cruising WaveAfter the wielder is healed, ATK will be increased by 24~48% for 8s. This can be triggered even when the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/69/Weapon_Tidal_Shadow.png'),
(188, 'Toukabou Shigure', 4, 510, 'Elemental Mastery 165(36)', 'Kaidan: Rainfall EarthbinderAfter an attack hits opponents, it will inflict an instance of Cursed Parasol upon one of them for 10s. This effect can be triggered once every 15s. If this opponent is defeated during Cursed Parasol\'s duration, Cursed Parasol\'s CD will be refreshed immediately. The character wielding this weapon will deal 16~32% more DMG to the opponent affected by Cursed Parasol.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/b5/Weapon_Toukabou_Shigure.png'),
(189, 'Wandering Evenstar', 4, 510, 'Elemental Mastery 165(36)', 'Wildling NightstarThe following effect will trigger every 10s: The equipping character will gain 24~48% of their Elemental Mastery as bonus ATK for 12s, with nearby party members gaining 30% of this buff for the same duration. Multiple instances of this weapon can allow this buff to stack. This effect will still trigger even if the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/44/Weapon_Wandering_Evenstar.png'),
(190, 'Wavebreaker\'s Fin', 4, 620, 'ATK 13.8%(3%)', 'Watatsumi WavewalkerFor every point of the entire party\'s combined maximum Energy capacity, the Elemental Burst DMG of the character equipping this weapon is increased by 0.12~0.24%. A maximum of 40~80% increased Elemental Burst DMG can be achieved this way.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/66/Weapon_Wavebreaker%27s_Fin.png'),
(191, 'Waveriding Whirl', 4, 454, 'Energy Recharge 61.3%(13.3%)', 'Fangs Flying To and FroDecreases Swimming Stamina consumption by 15%. In addition, for 10s after using an Elemental Skill, Max HP is increased by 20~40%. For every Hydro Elemental character in the party, Max HP is increased by another 12~24%, and the maximum increase that can be achieved in this way is 24~48%. Can be triggered once every 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/99/Weapon_Waveriding_Whirl.png'),
(192, 'Whiteblind', 4, 510, 'DEF 51.7%(11.3%)', 'Infusion BladeOn hit, Normal or Charged Attacks increase ATK and DEF by 6~12% for 6s. Max 4 stacks (24~48% total). Can only occur once every 0.5s.', 'https://static.wikia.nocookie.net/gensin-impact/images/0/04/Weapon_Whiteblind.png'),
(193, 'Windblume Ode', 4, 510, 'Elemental Mastery 165(36)', 'Windblume WishAfter using an Elemental Skill, receive a boon from the ancient wish of the Windblume, increasing ATK by 16~32% for 6s.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/38/Weapon_Windblume_Ode.png'),
(194, 'Wine and Song', 4, 565, 'Energy Recharge 30.6%(6.7%)', 'Ever-ChangingHitting an opponent with a Normal Attack decreases the Stamina consumption of Sprint or Alternate Sprint by 14~22% for 5s. Additionally, using a Sprint or Alternate Sprint ability increases ATK by 20~40% for 5s.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/c6/Weapon_Wine_and_Song.png'),
(195, 'Wolf-Fang', 4, 510, 'CRIT Rate 27.6%(6%)', 'Northwind WolfDMG dealt by Elemental Skill and Elemental Burst is increased by 16~32%. When an Elemental Skill hits an opponent, its CRIT Rate will be increased by 2~4%. When an Elemental Burst hits an opponent, its CRIT Rate will be increased by 2~4%. Both of these effects last 10s separately, have 4 max stacks, and can be triggered once every 0.1s.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/e3/Weapon_Wolf-Fang.png'),
(196, 'Xiphos\' Moonlight', 4, 510, 'Elemental Mastery 165(36)', 'Jinni\'s WhisperThe following effect will trigger every 10s: The equipping character will gain 0.036~0.072% Energy Recharge for each point of Elemental Mastery they possess for 12s, with nearby party members gaining 30% of this buff for the same duration. Multiple instances of this weapon can allow this buff to stack. This effect will still trigger even if the character is not on the field.', 'https://static.wikia.nocookie.net/gensin-impact/images/8/8a/Weapon_Xiphos%27_Moonlight.png'),
(197, 'Black Tassel', 3, 354, 'HP 46.9%(10.2%)', 'Bane of the SoftIncreases DMG against slimes by 40~80%.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/43/Weapon_Black_Tassel.png'),
(198, 'Bloodtainted Greatsword', 3, 354, 'Elemental Mastery 187(41)', 'Bane of Fire and ThunderIncreases DMG against opponents affected by Pyro or Electro by 12~24%.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/4a/Weapon_Bloodtainted_Greatsword.png'),
(199, 'Cool Steel', 3, 401, 'ATK 35.2%(7.7%)', 'Bane of Water and IceIncreases DMG against opponents affected by Hydro or Cryo by 12~24%.', 'https://static.wikia.nocookie.net/gensin-impact/images/9/9c/Weapon_Cool_Steel.png'),
(200, 'Dark Iron Sword', 3, 401, 'Elemental Mastery 141(31)', 'OverloadedUpon causing an Overloaded, Superconduct, Electro-Charged, Quicken, Aggravate, Hyperbloom, Lunar-Charged, or Electro-infused Swirl reaction, ATK is increased by 20~?% for 12s.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/3a/Weapon_Dark_Iron_Sword.png'),
(201, 'Debate Club', 3, 401, 'ATK 35.2%(7.7%)', 'Blunt ConclusionAfter using an Elemental Skill, Normal or Charged Attacks, on hit, deal an additional 60~120% ATK DMG in a small area. Effect lasts 15s. DMG can only occur once every 3s.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/74/Weapon_Debate_Club.png'),
(202, 'Emerald Orb', 3, 448, 'Elemental Mastery 94(20)', 'RapidsUpon causing a Vaporize, Electro-Charged, Frozen, Bloom, Lunar-Charged, Lunar-Bloom, or a Hydro-infused Swirl reaction, ATK is increased by 20~40% for 12s.', 'https://static.wikia.nocookie.net/gensin-impact/images/7/7c/Weapon_Emerald_Orb.png'),
(203, 'Ferrous Shadow', 3, 401, 'HP 35.2%(7.7%)', 'UnbendingWhen HP falls below 70~90%, increases Charged Attack DMG by 30~50%, and Charged Attacks become much harder to interrupt.', 'https://static.wikia.nocookie.net/gensin-impact/images/e/e9/Weapon_Ferrous_Shadow.png'),
(204, 'Fillet Blade', 3, 401, 'ATK 35.2%(7.7%)', 'GashOn hit, has 50% chance to deal 240~400% ATK DMG to a single enemy. Can only occur once every 15~11s.', 'https://static.wikia.nocookie.net/gensin-impact/images/f/f7/Weapon_Fillet_Blade.png'),
(205, 'Halberd', 3, 448, 'ATK 23.4%(5.1%)', 'HeavyNormal Attacks deal an additional 160~320% DMG. Can only occur once every 10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/4/41/Weapon_Halberd.png'),
(206, 'Harbinger of Dawn', 3, 401, 'CRIT DMG 46.9%(10.2%)', 'VigorousWhen HP is above 90%, increases CRIT Rate by 14~28%.', 'https://static.wikia.nocookie.net/gensin-impact/images/2/23/Weapon_Harbinger_of_Dawn.png'),
(207, 'Magic Guide', 3, 354, 'Elemental Mastery 187(41)', 'Bane of Storm and TideIncreases DMG against opponents affected by Hydro or Electro by 12~24%.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/39/Weapon_Magic_Guide.png'),
(208, 'Messenger', 3, 448, 'CRIT DMG 31.2%(6.8%)', 'Archer\'s MessageCharged Attack hits on weak spots deal an additional 100~200% ATK DMG as CRIT DMG. Can only occur once every 10s.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/38/Weapon_Messenger.png'),
(209, 'Otherworldly Story', 3, 401, 'Energy Recharge 39.0%(8.5%)', 'Energy ShowerEach Elemental Orb or Particle collected restores 1~2% HP.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/11/Weapon_Otherworldly_Story.png'),
(210, 'Raven Bow', 3, 448, 'Elemental Mastery 94(20)', 'Bane of Flame and WaterIncreases DMG against opponents affected by Hydro or Pyro by 12~24%.', 'https://static.wikia.nocookie.net/gensin-impact/images/d/d0/Weapon_Raven_Bow.png'),
(211, 'Recurve Bow', 3, 354, 'HP 46.9%(10.2%)', 'Cull the WeakDefeating an opponent restores 8~16% HP.', 'https://static.wikia.nocookie.net/gensin-impact/images/b/b5/Weapon_Recurve_Bow.png'),
(212, 'Sharpshooter\'s Oath', 3, 401, 'CRIT DMG 46.9%(10.2%)', 'PreciseIncreases DMG against weak spots by 24~48%.', 'https://static.wikia.nocookie.net/gensin-impact/images/5/52/Weapon_Sharpshooter%27s_Oath.png'),
(213, 'Skyrider Greatsword', 3, 401, 'Physical DMG Bonus 43.9%(9.6%)', 'CourageOn hit, Normal or Charged Attacks increase ATK by 6~10% for 6s. Max 4 stacks. Can only occur once every 0.5s.', 'https://static.wikia.nocookie.net/gensin-impact/images/6/6e/Weapon_Skyrider_Greatsword.png'),
(214, 'Skyrider Sword', 3, 354, 'Energy Recharge 51.7%(11.3%)', 'DeterminationUsing an Elemental Burst grants a 12~24% increase in ATK and Movement SPD for 15s.', 'https://static.wikia.nocookie.net/gensin-impact/images/3/34/Weapon_Skyrider_Sword.png'),
(215, 'Slingshot', 3, 354, 'CRIT Rate 31.2%(6.8%)', 'SlingshotIf a Normal or Charged Attack hits a target within 0.3s of being fired, increases DMG by 36~60%. Otherwise, decreases DMG by 10%.', 'https://static.wikia.nocookie.net/gensin-impact/images/c/ca/Weapon_Slingshot.png'),
(216, 'Thrilling Tales of Dragon Slayers', 3, 401, 'HP 35.2%(7.7%)', 'HeritageWhen switching characters, the new character taking the field has their ATK increased by 24~48% for 10s. This effect can only occur once every 20s.', 'https://static.wikia.nocookie.net/gensin-impact/images/1/19/Weapon_Thrilling_Tales_of_Dragon_Slayers.png'),
